  ('e1c1b57a-8b59-4eec-afe6-1edffa723c99', 'service', 'gasfiteria', 'Gasfitería y Reparación de Fugas Don Carlos', 'Más de 20 años en el barrio. Arreglo de tuberías, cañerías, sanitarios, termas e instalación de bombas de agua. Descuentos a vecinos mayores.', 'Carlos M.', 'Pasaje Los Laureles 142', 'A 2 cuadras del Parque Principal', -12.092, -77.0335, 'S/ 35 - S/ 60 (Tarifa vecinal)', null, 'active', 28, true, now() - interval '2 hours'),
  ('190ba421-3405-48bb-afaf-fc655d4753e1', 'service', 'electricidad', 'Electricidad Domiciliaria y Cuadros Eléctricos', 'Técnico certificado. Instalación de interruptores térmicos, cableado, luminarias LED y solución a cortocircuitos urgentes en la zona.', 'Ing. Javier Rojas', 'Av. Las Gardenias 450', 'Frente a la farmacia comunitaria', -12.0945, -77.0305, 'Evaluación rápida S/ 25', null, 'active', 19, true, now() - interval '5 hours'),
  ('bf95faa0-b9d4-407f-a705-f4b2b95c03fc', 'service', 'cerrajeria', 'Cerrajería 24 Horas "El Candado Vecinal"', 'Apertura de puertas sin daños, cambio de chapas, duplicado de llaves al instante. Atención a pie en menos de 10 minutos.', 'Miguel Benítez', 'Calle Los Pinos 210', 'Cerca a la bodega Don Pepe', -12.091, -77.031, 'Desde S/ 20', null, 'active', 34, true, now() - interval '1 days'),
  ('667a810a-c532-473d-afcd-243e29d50feb', 'service', 'mascotas', 'Paseo y Cuidado de Mascotas Responsable', 'Estudiante de veterinaria ofrece paseos grupales o individuales para perritos y visitas a gatos cuando viajas. Máximo cariño y paciencia.', 'Valeria Quispe', 'Jr. Bolognesi 330', 'Zona Parque de los Niños', -12.0955, -77.034, 'S/ 12 la hora', null, 'active', 15, true, now() - interval '3 days'),
  ('8d41f7d5-9734-43f3-a9fe-9dd18caa730d', 'favor_offer', 'herramientas', 'Presto Taladro Percutor y Escalera de Aluminio (4m)', 'Tengo un taladro Bosch con brocas para concreto y madera, y escalera tijera de 4 metros. Los presto a vecinos para arreglos de casa sin ningún costo.', 'Roberto Mendoza', 'Calle Las Acacias 120', 'Casa con reja verde', -12.0928, -77.029, 'GRATIS / Préstamo solidario', null, 'active', 14, true, now() - interval '1 day'),
  ('11144314-60f6-4c62-ae56-c9b91e2cc829', 'favor_offer', 'donacion', 'Donación: 3 Cajas de Libros Escolares de Primaria y Secundaria', 'Mis hijos ya terminaron el colegio. Son libros de matemáticas, ciencias, literatura y cuadernos de trabajo nuevos listos para familias que los necesiten.', 'Carmen Rosa', 'Jr. Grau 512', 'Costado del colegio Santa Rosa', -12.096, -77.0315, 'DONACIÓN GRATUITA', null, 'active', 22, true, now() - interval '6 hours'),
  ('5e032069-d6ed-40b5-a94b-7c3e24f81176', 'favor_request', 'ayuda_temporal', 'Necesito apoyo trasladando mueble pesado 3 cuadras', 'Soy una vecina de la tercera edad y compré una cajonera pequeña. Necesito ayuda de 1 o 2 vecinos para cargarla 300 metros.', 'Sra. Beatriz Flores', 'Calle Jacarandá 180', 'Tercer piso', -12.094, -77.033, 'Trueque: Ofrezco queque casero y limonada', null, 'active', 8, true, now() - interval '40 minutes'),
  ('57e2b5ff-a726-469f-ad51-adfd7c2f03e3', 'favor_offer', 'habilidades', 'Trueque de Saberes: Enseño Clases de Computación a cambio de Huerta', 'Enseño uso de celular, WhatsApp e internet a adultos mayores a cambio de que me enseñen a cultivar tomates y plantas aromáticas en azotea.', 'Daniel Vega', 'Pasaje San Martín 105', null, -12.0915, -77.0345, 'Trueque directo de habilidades', null, 'active', 11, true, now() - interval '1 days'),
  ('1712003a-fd6e-4888-a532-fb1ade73f5b9', 'support_group', 'primeros_auxilios', 'Brigada Vecinal de Primeros Auxilios y Triage', 'Grupo voluntario formado por vecinos enfermeros y bomberos del sector. Equipados con botiquín mayor, tensiómetro, oxímetro e inmovilizadores.', 'Dra. Elena Silva (Coordinadora)', 'Sede Comunal - Parque Central', 'Local Comunal Los Sauces', -12.093, -77.0322, 'Servicio Comunitario 100% Voluntario', 'alta', 'active', 52, true, now() - interval '1 day'),
  ('d454d2e6-6e33-4d01-a611-f87932b87d0c', 'support_group', 'rescate_movilidad', 'Comité de Alerta Temprana y Radio Vecinal', 'Red con megáfonos y radios walkie-talkie para alertar cortes imprevistos, aniegos, sismos o emergencias de seguridad en los cuadrantes 1 al 4.', 'Comité Vecinal de Defensa Civil', 'Cuadrante Central 1-4', null, -12.0918, -77.0308, null, 'media', 'active', 41, true, now() - interval '1 day'),
  ('42e749e4-7d20-4cb9-a4fe-19c18a5a8c75', 'emergency_resource', 'energia_luz', 'Punto Comunitario de Carga Solar y Generador Eléctrico', 'En caso de corte masivo de luz, habilitamos en nuestro garaje regletas de enchufes solares para cargar celulares de vecinos y equipos médicos.', 'Familia Paredes', 'Calle Los Álamos 310', null, -12.095, -77.031, 'Recurso Solidario Compartido', 'alta', 'active', 37, true, now() - interval '1 day'),
  ('0692c3ca-45fc-4c82-abff-52e7c7c887b9', 'emergency_resource', 'agua_alimentos', 'Tanque Comunitario de Agua Potable y Filtro Cerámico', 'Reserva comunitaria de 2,500 litros de agua limpia con pastillas purificadoras para abastecer a familias en desabastecimiento.', 'Olla Común "Corazón de Barrio"', 'Jr. Amazonas 102', null, -12.0938, -77.035, 'Abastecimiento Gratuito de Emergencia', 'critica', 'active', 46, true, now() - interval '1 day'),
  ('8cc31f55-e002-4f88-af68-f7836995b4c3', 'emergency_need', 'vulnerabilidad_mayor', 'URGENTE: Adulto mayor de 82 años requiere apoyo con recarga de oxígeno', 'Don Hernán vive solo en segundo piso. Se le está agotando el balón de respaldo y no cuenta con movilidad para trasladarlo.', 'Rosa (Vecina contigua)', 'Pasaje Olivos 115 - Dpto 201', null, -12.0925, -77.0315, 'Auxilio Humanitario Inmediato', 'critica', 'active', 18, true, now() - interval '15 minutes'),
  ('3f814d8f-82d6-4520-a133-50c8a5908156', 'emergency_need', 'energia_luz', 'Filtración grave de agua amenaza cuadro eléctrico vecinal', 'Rotura de matriz en vereda exterior está inundando la caja de fusibles comunitaria de 4 casas contiguas.', 'Junta Vecinal Sector B', 'Esq. Las Acacias y Bolognesi', null, -12.0948, -77.0332, null, 'alta', 'in_progress', 9, true, now() - interval '45 minutes');

insert into public.reviews (post_id, author_name, comment, is_neighbor_verified, created_at) values
  ('e1c1b57a-8b59-4eec-afe6-1edffa723c99', 'Doña Teresa (Vecina Jr. Robles)', 'Don Carlos vino en 15 minutos cuando se rompió la tubería del baño. Muy honrado y dejó todo limpio.', true, now() - interval '1 day'),
  ('e1c1b57a-8b59-4eec-afe6-1edffa723c99', 'Marco Aurelio', '100% recomendado por los vecinos de la cuadra 3. Cobra lo justo.', true, now() - interval '4 days'),
  ('190ba421-3405-48bb-afaf-fc655d4753e1', 'Patricia Solís', 'Me arregló la llave general que botaba chispas en la noche. Muy puntual y profesional.', true, now() - interval '1 weeks'),
  ('bf95faa0-b9d4-407f-a705-f4b2b95c03fc', 'Lucía G.', 'Olvidé mis llaves adentro con la olla prendida y Miguel llegó corriendo. Nos salvó el día.', true, now() - interval '3 days'),
  ('8d41f7d5-9734-43f3-a9fe-9dd18caa730d', 'Esteban C.', 'Roberto me prestó el taladro el fin de semana para colgar mis repisas. ¡Gran iniciativa comunitaria!', true, now() - interval '1 day');
